const ts = (s) => { const [seconds, nanos] = s.split('.'); return { seconds: Number(seconds), nanos: Number(nanos) } }
const acct = (id) => { const [shardNum, realmNum, accountNum] = id.split('.').map(Number); return { shardNum, realmNum, accountNum } }

const main = async () => {
